// generated by gemini-3.5-flash-lite for PR #6076 (round 0): unflatten_roundtrip_flatten
// intent: Probes roundtrip consistency of flatten and unflatten on a complex nested structure.
#include <nlohmann/json.hpp>
#include <iostream>
int main() {
    try {
        nlohmann::json original = {
            {"a", {1, 2}},
            {"b", {{"c", 3}, {"d", 4}}}
        };
        nlohmann::json flat = original.flatten();
        nlohmann::json unflat = flat.unflatten();
        std::cout << (original == unflat) << "\n";
    } catch (const std::exception& e) {
        std::cout << e.what() << "\n";
    }
}
